#include <stdlib.h>
#include <string.h>
#include <math.h>
/* sparse shortest augmenting path LAP, with dense dual check */
typedef struct {double d; int j;} HE;
static void hpush(HE*h,int*hn,double d,int j){int i=(*hn)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*hn){HE top=h[0];HE last=h[--(*hn)];int n=*hn,i=0;while(1){int c=2*i+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}if(n>0)h[i]=last;return top;}

static double qsel(double*a,int n,int k){ /* k-th smallest (0-based) */
  int l=0,r=n-1;
  while(l<r){double x=a[(l+r)>>1];int i=l,j=r;
    while(i<=j){while(a[i]<x)i++;while(a[j]>x)j--;if(i<=j){double t=a[i];a[i]=a[j];a[j]=t;i++;j--;}}
    if(k<=j)r=j;else if(k>=i)l=i;else return a[k];}
  return a[k];
}

static int solve_sparse(int n,const double*C,const int*rp,const int*ci,int*rowc,int*colr,double*u,double*v,
  double*dist,int*pred,int*done,int*vis,HE*heap,int*rowsr){
  for(int j=0;j<n;j++){v[j]=INFINITY;colr[j]=-1;}
  for(int i=0;i<n;i++)for(int e=rp[i];e<rp[i+1];e++){int j=ci[e];double c=C[(size_t)i*n+j];if(c<v[j])v[j]=c;}
  for(int j=0;j<n;j++)if(!isfinite(v[j]))return -1;
  for(int i=0;i<n;i++){double m=INFINITY;int bj=-1;for(int e=rp[i];e<rp[i+1];e++){int j=ci[e];double r=C[(size_t)i*n+j]-v[j];if(r<m){m=r;bj=j;}}
    if(bj<0)return -1;u[i]=m;rowc[i]=-1;if(colr[bj]<0&&1){colr[bj]=i;rowc[i]=bj;}}
  for(int j=0;j<n;j++){dist[j]=INFINITY;done[j]=0;}
  for(int s=0;s<n;s++){ if(rowc[s]>=0)continue;
    int hn=0,nv=0,nr=0; int i=s; double di=0; int jend=-1; double D=0;
    rowsr[nr++]=s;
    while(1){
      double ui=u[i];
      for(int e=rp[i];e<rp[i+1];e++){int j=ci[e];if(done[j])continue;double nd=di+C[(size_t)i*n+j]-ui-v[j];
        if(nd<dist[j]){if(!isfinite(dist[j]))vis[nv++]=j;dist[j]=nd;pred[j]=i;hpush(heap,&hn,nd,j);}}
      int j=-1;
      while(hn>0){HE t=hpop(heap,&hn);if(done[t.j]||t.d>dist[t.j])continue;j=t.j;break;}
      if(j<0)return -1;
      done[j]=1;
      if(colr[j]<0){jend=j;D=dist[j];break;}
      i=colr[j];di=dist[j];rowsr[nr++]=i;
    }
    /* update potentials */
    for(int k=0;k<nr;k++){int r=rowsr[k];double dr=(r==s)?0:dist[rowc[r]];if(dr<D)u[r]+=D-dr;}
    for(int k=0;k<nv;k++){int j=vis[k];if(done[j]&&dist[j]<D)v[j]-=D-dist[j];}
    /* augment */
    int j=jend;while(1){int r=pred[j];int pj=rowc[r];colr[j]=r;rowc[r]=j;if(r==s)break;j=pj;}
    for(int k=0;k<nv;k++){int j2=vis[k];dist[j2]=INFINITY;done[j2]=0;}
  }
  return 0;
}

int lap(int n,const double*C,int k,int*rowc){
  size_t nn=(size_t)n*n;
  char*mask=calloc(nn,1);
  double*buf=malloc(sizeof(double)*n);
  int*rp=malloc(sizeof(int)*(n+1)); int cap=n*4*k+16; int*ci=malloc(sizeof(int)*cap);
  int*colr=malloc(sizeof(int)*n);double*u=malloc(sizeof(double)*n),*v=malloc(sizeof(double)*n),*dist=malloc(sizeof(double)*n);
  int*pred=malloc(sizeof(int)*n),*done=malloc(sizeof(int)*n),*vis=malloc(sizeof(int)*n),*rowsr=malloc(sizeof(int)*(n+1));
  HE*heap=malloc(sizeof(HE)*(nn+n));
  if(k>n)k=n;
  for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;memcpy(buf,row,sizeof(double)*n);double t=qsel(buf,n,k-1);
    for(int j=0;j<n;j++)if(row[j]<=t)mask[(size_t)i*n+j]=1;}
  for(int j=0;j<n;j++){for(int i=0;i<n;i++)buf[i]=C[(size_t)i*n+j];double t=qsel(buf,n,k-1);
    for(int i=0;i<n;i++)if(C[(size_t)i*n+j]<=t)mask[(size_t)i*n+j]=1;}
  int ret=-2;
  for(int iter=0;iter<50;iter++){
    int ne=0;for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(mask[(size_t)i*n+j])ne++;
    if(ne>cap){cap=ne;ci=realloc(ci,sizeof(int)*cap);}
    ne=0;for(int i=0;i<n;i++){rp[i]=ne;for(int j=0;j<n;j++)if(mask[(size_t)i*n+j])ci[ne++]=j;}rp[n]=ne;
    int r=solve_sparse(n,C,rp,ci,rowc,colr,u,v,dist,pred,done,vis,heap,rowsr);
    if(r<0){ /* infeasible: double k */
      k*=2;if(k>n)k=n;
      for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;memcpy(buf,row,sizeof(double)*n);double t=qsel(buf,n,k-1);
        for(int j=0;j<n;j++)if(row[j]<=t)mask[(size_t)i*n+j]=1;}
      continue;}
    int viol=0;
    for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;double ui=u[i];for(int j=0;j<n;j++){if(row[j]-ui-v[j]< -1e-12){if(!mask[(size_t)i*n+j]){mask[(size_t)i*n+j]=1;viol++;}}}}
    if(viol==0){ret=0;break;}
  }
  free(mask);free(buf);free(rp);free(ci);free(colr);free(u);free(v);free(dist);free(pred);free(done);free(vis);free(rowsr);free(heap);
  return ret;
}
