#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdio.h>
typedef struct {double d; int j;} HE;
static inline void hpush(HE*h,int*hn,double d,int j){int i=(*hn)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static inline HE hpop(HE*h,int*hn){HE top=h[0];HE last=h[--(*hn)];int n=*hn,i=0;while(1){int c=2*i+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}if(n>0)h[i]=last;return top;}

static double qsel(double*a,int n,int k){
  int l=0,r=n-1;
  while(l<r){double x=a[(l+r)>>1];int i=l,j=r;
    while(i<=j){while(a[i]<x)i++;while(a[j]>x)j--;if(i<=j){double t=a[i];a[i]=a[j];a[j]=t;i++;j--;}}
    if(k<=j)r=j;else if(k>=i)l=i;else return a[k];}
  return a[k];
}

/* adjacency: per-row dynamic lists */
typedef struct { int n; int *cnt, *cap; int **adj; } G_t;
static void gadd(G_t*g,int i,int j){ if(g->cnt[i]==g->cap[i]){g->cap[i]*=2;g->adj[i]=realloc(g->adj[i],sizeof(int)*g->cap[i]);} g->adj[i][g->cnt[i]++]=j; }

/* Dijkstra augment from all free rows. Requires reduced costs C-u-v >= 0 on edges, and tight on matched edges. */
static int augment_all(int n,const double*C,G_t*g,int*rowc,int*colr,double*u,double*v,
  double*dist,int*pred,char*done,int*vis,HE*heap,int*rowsr){
  for(int s=0;s<n;s++){ if(rowc[s]>=0)continue;
    int hn=0,nv=0,nr=0; int i=s; double di=0; int jend=-1; double D=0;
    rowsr[nr++]=s;
    while(1){
      double ui=u[i]; const double*row=C+(size_t)i*n; const int*a=g->adj[i]; int c=g->cnt[i];
      for(int e=0;e<c;e++){int j=a[e];if(done[j])continue;double nd=di+row[j]-ui-v[j];
        if(nd<dist[j]){if(dist[j]==INFINITY)vis[nv++]=j;dist[j]=nd;pred[j]=i;hpush(heap,&hn,nd,j);}}
      int j=-1;
      while(hn>0){HE t=hpop(heap,&hn);if(done[t.j]||t.d>dist[t.j])continue;j=t.j;break;}
      if(j<0){for(int k=0;k<nv;k++){dist[vis[k]]=INFINITY;done[vis[k]]=0;}return -1;}
      done[j]=1;
      if(colr[j]<0){jend=j;D=dist[j];break;}
      i=colr[j];di=dist[j];rowsr[nr++]=i;
    }
    for(int k=0;k<nr;k++){int r=rowsr[k];double dr=(r==s)?0:dist[rowc[r]];if(dr<D)u[r]+=D-dr;}
    for(int k=0;k<nv;k++){int j=vis[k];if(done[j]&&dist[j]<D)v[j]-=D-dist[j];}
    int j=jend;while(1){int r=pred[j];int pj=rowc[r];colr[j]=r;rowc[r]=j;if(r==s)break;j=pj;}
    for(int k=0;k<nv;k++){int j2=vis[k];dist[j2]=INFINITY;done[j2]=0;}
  }
  return 0;
}

int lap(int n,const double*C,int k,int*rowc){
  if(k>n)k=n;
  size_t nn=(size_t)n*n;
  char*mask=calloc(nn,1);
  double*buf=malloc(sizeof(double)*n);
  G_t g; g.n=n; g.cnt=calloc(n,sizeof(int)); g.cap=malloc(sizeof(int)*n); g.adj=malloc(sizeof(int*)*n);
  for(int i=0;i<n;i++){g.cap[i]=4*k+8;g.adj[i]=malloc(sizeof(int)*g.cap[i]);}
  int*colr=malloc(sizeof(int)*n);double*u=malloc(sizeof(double)*n),*v=malloc(sizeof(double)*n),*dist=malloc(sizeof(double)*n);
  int*pred=malloc(sizeof(int)*n),*vis=malloc(sizeof(int)*n),*rowsr=malloc(sizeof(int)*(n+1));
  char*done=calloc(n,1);
  HE*heap=malloc(sizeof(HE)*(nn+n));
  /* candidate edges: k nearest per row and per column */
  for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;memcpy(buf,row,sizeof(double)*n);double t=qsel(buf,n,k-1);
    char*mr=mask+(size_t)i*n; for(int j=0;j<n;j++)if(row[j]<=t){mr[j]=1;gadd(&g,i,j);}}
  for(int j=0;j<n;j++){for(int i=0;i<n;i++)buf[i]=C[(size_t)i*n+j];double t=qsel(buf,n,k-1);
    for(int i=0;i<n;i++){size_t id=(size_t)i*n+j; if(C[id]<=t && !mask[id]){mask[id]=1;gadd(&g,i,j);}}}
  /* init duals: v = column min over edges, u = row min of reduced */
  for(int j=0;j<n;j++){v[j]=INFINITY;colr[j]=-1;dist[j]=INFINITY;}
  for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;for(int e=0;e<g.cnt[i];e++){int j=g.adj[i][e];if(row[j]<v[j])v[j]=row[j];}}
  for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;double m=INFINITY;int bj=-1;
    for(int e=0;e<g.cnt[i];e++){int j=g.adj[i][e];double r=row[j]-v[j];if(r<m){m=r;bj=j;}}
    u[i]=m;rowc[i]=-1;if(colr[bj]<0){colr[bj]=i;rowc[i]=bj;}}
  int ret=-2;
  for(int iter=0;iter<200;iter++){
    int r=augment_all(n,C,&g,rowc,colr,u,v,dist,pred,done,vis,heap,rowsr);
    if(r<0){ /* infeasible on sparse graph: add more edges per row */
      k*=2; if(k>n)k=n;
      for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;memcpy(buf,row,sizeof(double)*n);double t=qsel(buf,n,k-1);
        char*mr=mask+(size_t)i*n; for(int j=0;j<n;j++)if(row[j]<=t&&!mr[j]){mr[j]=1;gadd(&g,i,j);}}
      /* restore dual feasibility */
      for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;double m=INFINITY;
        for(int e=0;e<g.cnt[i];e++){int j=g.adj[i][e];double rr=row[j]-v[j];if(rr<m)m=rr;}
        if(m<u[i]){u[i]=m; if(rowc[i]>=0){colr[rowc[i]]=-1;rowc[i]=-1;}}}
      continue;}
    /* full dense check: v fixed, u_i = min_j C_ij - v_j */
    int viol=0;
    for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;char*mr=mask+(size_t)i*n;double ui=u[i];double m=ui;
      for(int j=0;j<n;j++){double rr=row[j]-v[j]; if(rr<ui-1e-12){ if(!mr[j]){mr[j]=1;gadd(&g,i,j);} viol++; if(rr<m)m=rr;}}
      if(m<ui){u[i]=m; colr[rowc[i]]=-1; rowc[i]=-1;}}
    if(getenv("LAPDBG"))fprintf(stderr,"iter %d viol %d k %d\n",iter,viol,k);
    if(viol==0){ret=0;break;}
  }
  free(mask);free(buf);for(int i=0;i<n;i++)free(g.adj[i]);free(g.adj);free(g.cnt);free(g.cap);
  free(colr);free(u);free(v);free(dist);free(pred);free(done);free(vis);free(rowsr);free(heap);
  return ret;
}
