    while(1){
      double ui=u[i]; const int*a=g->adj[i]; const double*w=g->w[i]; int c=g->cnt[i];
      double base=di-ui;
      for(int e=0;e<c;e++){int j=a[e];double nd=base+w[e]-v[j];
