/* forward auction with eps-scaling; v = -price. returns 0 ok, -1 if stalled */
static double EPS0=0.02, EPSF=1e-8, EFAC=0.2;
static int auction(int n,G_t*g,int*rowc,int*colr,double*p,int*q){
  for(int j=0;j<n;j++)p[j]=0;
  long maxbids=(long)n*20000;
  long bids=0;
  for(double eps=EPS0;;eps*=EFAC){
    if(eps<EPSF)eps=EPSF;
    int qh=0,qt=0;
    for(int j=0;j<n;j++)colr[j]=-1;
    for(int i=0;i<n;i++){rowc[i]=-1;q[qt++]=i;}
    int qs=n+1; /* circular queue size */
    int cntq=n;
    while(cntq>0){
      int i=q[qh];qh++; if(qh==qs)qh=0; cntq--;
      const int*a=g->adj[i];const double*w=g->w[i];int c=g->cnt[i];
      double b1=INFINITY,b2=INFINITY;int j1=-1;
      for(int e=0;e<c;e++){double x=w[e]+p[a[e]];if(x<b2){if(x<b1){b2=b1;b1=x;j1=a[e];}else b2=x;}}
      if(b2==INFINITY)b2=b1+1.0;
      p[j1]+=b2-b1+eps;
      int o=colr[j1]; colr[j1]=i; rowc[i]=j1;
      if(o>=0){rowc[o]=-1;q[qt++]=o;if(qt==qs)qt=0;cntq++;}
      if(++bids>maxbids)return -1;
    }
    if(eps<=EPSF)break;
  }
  if(dbg)fprintf(stderr,"bids %ld\n",bids);
  return 0;
}

