#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdio.h>
#include <time.h>
static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+1e-9*t.tv_nsec;}
static int dbg=0;
static double qsel(double*a,int n,int k){
  int l=0,r=n-1;
  while(l<r){double x=a[(l+r)>>1];int i=l,j=r;
    while(i<=j){while(a[i]<x)i++;while(a[j]>x)j--;if(i<=j){double t=a[i];a[i]=a[j];a[j]=t;i++;j--;}}
    if(k<=j)r=j;else if(k>=i)l=i;else return a[k];}
  return a[k];
}
typedef struct { int n; int *cnt,*cap; int **adj; double **w; } G_t;
static void gadd(G_t*g,int i,int j,double c){ if(g->cnt[i]==g->cap[i]){g->cap[i]*=2;g->adj[i]=realloc(g->adj[i],sizeof(int)*g->cap[i]);g->w[i]=realloc(g->w[i],sizeof(double)*g->cap[i]);} g->w[i][g->cnt[i]]=c; g->adj[i][g->cnt[i]++]=j; }

static double EPS0=0.05, EPSF=1e-4, EFAC=0.1, KF=30;
static long nbids;
/* forward auction, eps-scaling, on sparse graph. prices p=-v. */
static int auction(int n,G_t*g,int*rowc,int*colr,double*v,int*q){
  int first=1; nbids=0;
  for(int j=0;j<n;j++)colr[j]=-1;
  for(int i=0;i<n;i++)rowc[i]=-1;
  for(double eps=EPS0;;eps*=EFAC){
    if(eps<EPSF)eps=EPSF;
    int qh=0,qt=0,qs=n+1,cntq=0;
    for(int i=0;i<n;i++){
      if(!first && rowc[i]>=0){
        const int*a=g->adj[i];const double*w=g->w[i];int c=g->cnt[i];double b1=INFINITY;int rc=rowc[i];
        for(int e=0;e<c;e++){double x=w[e]-v[a[e]];b1=x<b1?x:b1;}
        double mine=INFINITY; for(int e=0;e<c;e++)if(a[e]==rc){mine=w[e]-v[rc];break;}
        if(mine<=b1+eps)continue;
        colr[rc]=-1;rowc[i]=-1;
      }
      q[qt++]=i;cntq++;
    }
    first=0;
    while(cntq>0){
      int i=q[qh++]; if(qh==qs)qh=0; cntq--;
      const int*a=g->adj[i];const double*w=g->w[i];int c=g->cnt[i];
      double b1=INFINITY,b2=INFINITY;int j1=-1;
      for(int e=0;e<c;e++){double x=w[e]-v[a[e]];if(x<b2){if(x<b1){b2=b1;b1=x;j1=a[e];}else b2=x;}}
      if(b2==INFINITY)b2=b1+1.0;
      v[j1]-=b2-b1+eps;
      int o=colr[j1]; colr[j1]=i; rowc[i]=j1;
      if(o>=0){rowc[o]=-1;q[qt++]=o;if(qt==qs)qt=0;cntq++;}
      if(++nbids>(long)n*5000)return -1;
    }
    if(eps<=EPSF)break;
  }
  return 0;
}

/* Dijkstra SAP on sparse graph. Requires reduced costs >=0 on graph edges, =0 on matched. Returns -1 if some row can't be matched (rowsr[0..g_nr) = reached rows). */
static int g_nr;
static int sap(int n,G_t*g,int*rowc,int*colr,double*u,double*v,
  double*dist,int*pred,char*done,int*vis,int*rowsr,int*hp,int*pos){
  for(int s=0;s<n;s++){ if(rowc[s]>=0)continue;
    int hn=0,nv=0,nr=0; int i=s; double di=0; int jend=-1; double D=0;
    double bestfree=INFINITY; int bfj=-1;
    rowsr[nr++]=s;
    while(1){
      const int*a=g->adj[i]; const double*w=g->w[i]; int c=g->cnt[i];
      double base=di-u[i];
      for(int e=0;e<c;e++){int j=a[e];double nd=base+w[e]-v[j];
        if(nd<dist[j] && nd<bestfree && !done[j]){
          int k;
          if(dist[j]==INFINITY){vis[nv++]=j;k=hn++;} else k=pos[j];
          dist[j]=nd;pred[j]=i;
          if(colr[j]<0){bestfree=nd;bfj=j;}
          while(k>0){int p=(k-1)>>1;int pj=hp[p];if(dist[pj]<=nd)break;hp[k]=pj;pos[pj]=k;k=p;}
          hp[k]=j;pos[j]=k;
        }}
      int j=-1;
      if(hn>0 && dist[hp[0]]<=bestfree){
        j=hp[0]; int last=hp[--hn]; double ld=dist[last]; int k=0;
        while(1){int c2=2*k+1;if(c2>=hn)break;if(c2+1<hn&&dist[hp[c2+1]]<dist[hp[c2]])c2++;if(dist[hp[c2]]>=ld)break;hp[k]=hp[c2];pos[hp[k]]=k;k=c2;}
        if(hn>0){hp[k]=last;pos[last]=k;}
      } else j=bfj;
      if(j<0){for(int k=0;k<nv;k++){dist[vis[k]]=INFINITY;done[vis[k]]=0;}g_nr=nr;return -1;}
      done[j]=1;
      if(colr[j]<0){jend=j;D=dist[j];break;}
      i=colr[j];di=dist[j];rowsr[nr++]=i;
    }
    for(int k=0;k<nr;k++){int r=rowsr[k];double dr=(r==s)?0:dist[rowc[r]];if(dr<D)u[r]+=D-dr;}
    for(int k=0;k<nv;k++){int j=vis[k];if(done[j]&&dist[j]<D)v[j]-=D-dist[j];}
    int j=jend;while(1){int r=pred[j];int pj=rowc[r];colr[j]=r;rowc[r]=j;if(r==s)break;j=pj;}
    for(int k=0;k<nv;k++){int j2=vis[k];dist[j2]=INFINITY;done[j2]=0;}
  }
  return 0;
}

static inline double rowmin(const double*row,const double*v,int n){
  double m0=INFINITY,m1=INFINITY,m2=INFINITY,m3=INFINITY; int j=0;
  for(;j+4<=n;j+=4){double a=row[j]-v[j],b=row[j+1]-v[j+1],c=row[j+2]-v[j+2],d=row[j+3]-v[j+3];
    m0=a<m0?a:m0;m1=b<m1?b:m1;m2=c<m2?c:m2;m3=d<m3?d:m3;}
  for(;j<n;j++){double a=row[j]-v[j];m0=a<m0?a:m0;}
  m0=m1<m0?m1:m0;m2=m3<m2?m3:m2;return m2<m0?m2:m0;
}

/* Exact dense LAP. Returns 0 when the dense optimality certificate holds. */
int lap(int n,const double*C,int*rowc){
  dbg=getenv("LAPDBG")?atoi(getenv("LAPDBG")):0;
  if(getenv("KF"))KF=atof(getenv("KF"));
  if(getenv("EPS0"))EPS0=atof(getenv("EPS0")); if(getenv("EPSF"))EPSF=atof(getenv("EPSF")); if(getenv("EFAC"))EFAC=atof(getenv("EFAC"));
  double T0=now();
  double*buf=malloc(sizeof(double)*n);
  G_t g; g.n=n; g.cnt=calloc(n,sizeof(int)); g.cap=malloc(sizeof(int)*n); g.adj=malloc(sizeof(int*)*n); g.w=malloc(sizeof(double*)*n);
  int*colr=malloc(sizeof(int)*n);double*u=malloc(sizeof(double)*n),*v=malloc(sizeof(double)*n),*dist=malloc(sizeof(double)*n);
  int*pred=malloc(sizeof(int)*n),*vis=malloc(sizeof(int)*n),*rowsr=malloc(sizeof(int)*(n+1)),*q=malloc(sizeof(int)*(n+2));
  int*hp=malloc(sizeof(int)*n),*pos=malloc(sizeof(int)*n);
  char*done=calloc(n,1);
  int cap0=(int)(KF*2)+8; if(cap0>n)cap0=n;
  for(int i=0;i<n;i++){g.cap[i]=cap0;g.adj[i]=malloc(sizeof(int)*cap0);g.w[i]=malloc(sizeof(double)*cap0);}
  /* global raw-cost threshold from sample rows */
  double T;
  { int S=n<16?n:16; double tk[16]; int kk=(int)KF; if(kk<2)kk=2; if(kk>n)kk=n;
    for(int s2=0;s2<S;s2++){int i=(int)((long)s2*n/S);memcpy(buf,C+(size_t)i*n,sizeof(double)*n);tk[s2]=qsel(buf,n,kk-1);}
    T=qsel(tk,S,S/2); }
  for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;
    for(int j=0;j<n;j++)if(row[j]<=T)gadd(&g,i,j,row[j]);
    if(g.cnt[i]<4){ g.cnt[i]=0; memcpy(buf,row,sizeof(double)*n); double th=qsel(buf,n,3);
      for(int j=0;j<n;j++)if(row[j]<=th)gadd(&g,i,j,row[j]); }
  }
  for(int j=0;j<n;j++){v[j]=0;dist[j]=INFINITY;}
  double T1=now(); if(dbg){long te=0;for(int i=0;i<n;i++)te+=g.cnt[i];fprintf(stderr,"build %.3fms edges %ld T %g\n",(T1-T0)*1e3,te,T);}
