  if(ar==0){
    for(int i=0;i<n;i++){int j=rowc[i];u[i]=C[(size_t)i*n+j]-v[j];}
    for(int i=0;i<n;i++){const int*a=g.adj[i];const double*w=g.w[i];int c=g.cnt[i];double ui=u[i];
      for(int e=0;e<c;e++){int j=a[e];double r=w[e]-ui;if(r<v[j])v[j]=r;}}
    for(int i=0;i<n;i++){int j=rowc[i];if(C[(size_t)i*n+j]-v[j]-u[i]>0){colr[j]=-1;rowc[i]=-1;}}
  }
  for(int i=0;i<n;i++)if(rowc[i]<0){const int*a=g.adj[i];const double*w=g.w[i];int c=g.cnt[i];double m=INFINITY;
    for(int e=0;e<c;e++){double r=w[e]-v[a[e]];if(r<m)m=r;} u[i]=m;}
  double T2=now(); if(dbg){int nf=0;for(int i=0;i<n;i++)nf+=rowc[i]<0;fprintf(stderr,"auction %.3fms bids %ld free %d\n",(T2-T1)*1e3,nbids,nf);}
  int ret=-1;
  for(int iter=0;iter<1000;iter++){
    double Ta=now();
