        double m=u[i];
        for(int j=0;j<n;j++){double r=row[j]-v[j]; if(r<=th && !done[j]){gadd(&g,i,j,row[j]); if(r<m)m=r;}}
        for(int e=0;e<g.cnt[i];e++)done[g.adj[i][e]]=0;
        if(m<u[i]){u[i]=m; if(rowc[i]>=0){colr[rowc[i]]=-1;rowc[i]=-1;}}
      }
