      int c=0; for(int j=0;j<n;j++){if(row[j]<=th){c++; if(row[j]>T)cc[j]++;}} rc[i]=c;}
    g.rp[i+1]=g.rp[i]+rc[i];}
  g.cj=malloc(sizeof(int)*g.rp[n]); g.cw=malloc(sizeof(double)*g.rp[n]);
  for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;double th=rth[i];int o=g.rp[i];
    for(int j=0;j<n;j++){if(row[j]<=th){g.cj[o]=j;g.cw[o]=row[j];o++;}}}
  for(int j=0;j<n;j++)if(cc[j]<kmin){
    for(int i=0;i<n;i++)buf[i]=C[(size_t)i*n+j]; double th=qsel(buf,n,kmin-1);
    for(int i=0;i<n;i++){double c=C[(size_t)i*n+j]; if(c<=th && c>rth[i])eadd(&ex,i,j,c);}}
  gmerge(&g,&ex);
  free(rth);
  double T1=now();
  int ar=auction(n,&g,rowc,colr,v,q);
  double T2=now();
  if(ar<0){for(int i=0;i<n;i++)rowc[i]=-1;for(int j=0;j<n;j++){colr[j]=-1;v[j]=0;}}
  if(ar==0){
    /* eps-CS -> exact CS on graph while keeping assignment (label-correcting) */
    for(int i=0;i<n;i++){int j=rowc[i];u[i]=C[(size_t)i*n+j]-v[j];}
    char*inq=done; int qh=0,qt=0,qs=n+1,cntq=0; long relax=0; int okr=1;
