  }
  for(int i=0;i<n;i++)if(rowc[i]<0){double m=INFINITY;for(int e=g.rp[i];e<g.rp[i+1];e++){double r=g.cw[e]-v[g.cj[e]];if(r<m)m=r;} u[i]=m;}
  for(int j=0;j<n;j++)dist[j]=INFINITY;
  double T3=now();
  if(dbg)fprintf(stderr,"build %.3fms E %d auction %.3fms bids %ld repair %.3fms\n",(T1-T0)*1e3,g.rp[n],(T2-T1)*1e3,nbids,(T3-T2)*1e3);
  for(int iter=0;iter<1000;iter++){
    double Ta=now();
    while(sap(n,&g,rowc,colr,u,v,dist,pred,done,vis,rowsr,hp,pos)<0){
      for(int k=0;k<g_nr;k++){int i=rowsr[k];const double*row=C+(size_t)i*n;int c=g.rp[i+1]-g.rp[i]; if(c>=n)continue;
        int want=2*c; if(want>n)want=n;
        for(int j=0;j<n;j++)buf[j]=row[j]-v[j];
        double th=qsel(buf,n,want-1);
        for(int e=g.rp[i];e<g.rp[i+1];e++)done[g.cj[e]]=1;
        double m=u[i];
        for(int j=0;j<n;j++){double r=row[j]-v[j]; if(r<=th && !done[j]){eadd(&ex,i,j,row[j]); if(r<m)m=r;}}
        for(int e=g.rp[i];e<g.rp[i+1];e++)done[g.cj[e]]=0;
        if(m<u[i]){u[i]=m; if(rowc[i]>=0){colr[rowc[i]]=-1;rowc[i]=-1;}}
      }
      gmerge(&g,&ex);
    }
    double Tb=now();
    int vrows=0,vcols=0;
    for(int i=0;i<n;i++){rm[i]=rowmin(C+(size_t)i*n,v,n); if(rm[i]<u[i]-1e-12)vrows++;}
    if(vrows){
      for(int j=0;j<n;j++)cm[j]=INFINITY;
      for(int i=0;i<n;i++){const double*row=C+(size_t)i*n;double ui=u[i];for(int j=0;j<n;j++){double r=row[j]-ui;cm[j]=r<cm[j]?r:cm[j];}}
      for(int j=0;j<n;j++)if(cm[j]<v[j]-1e-12)vcols++;
      int colside = vcols<vrows;
      for(int i=0;i<n;i++){
        if(rm[i]<u[i]-1e-12){const double*row=C+(size_t)i*n;double ui=u[i];
          for(int e=g.rp[i];e<g.rp[i+1];e++)done[g.cj[e]]=1;
          for(int j=0;j<n;j++){if(row[j]-v[j]<ui && !done[j])eadd(&ex,i,j,row[j]);}
          for(int e=g.rp[i];e<g.rp[i+1];e++)done[g.cj[e]]=0;
          if(!colside){u[i]=rm[i]; colr[rowc[i]]=-1; rowc[i]=-1;}
        }}
      if(colside){ for(int j=0;j<n;j++)if(cm[j]<v[j]-1e-12){v[j]=cm[j]; if(colr[j]>=0){rowc[colr[j]]=-1;colr[j]=-1;}}}
      gmerge(&g,&ex);
    }
    if(dbg)fprintf(stderr,"sap %.3fms iter %d vrows %d vcols %d check %.3fms\n",(Tb-Ta)*1e3,iter,vrows,vcols,(now()-Tb)*1e3);
    if(vrows==0){ret=0;break;}
  }
  if(ret==0){
    for(int j=0;j<n;j++)if(colr[j]<0){ret=-6;break;}
    for(int i=0;i<n&&ret==0;i++){const double*row=C+(size_t)i*n;int j=rowc[i];
      if(j<0 || row[j]-v[j] > rowmin(row,v,n)+1e-12){ret=-5;}}
  }
  if(dbg)fprintf(stderr,"total %.3fms ret %d\n",(now()-T0)*1e3,ret);
  free(g.rp);free(g.cj);free(g.cw);free(ex.i);free(ex.j);free(ex.c);
  free(buf);free(colr);free(u);free(v);free(dist);free(pred);free(done);free(vis);free(rowsr);free(q);free(hp);free(pos);free(rc);free(cc);free(rm);free(cm);
  return ret;
}
